import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import api from '../utils/api';

const AuthContext = createContext(null);

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  const loadUser = useCallback(async () => {
    const token = localStorage.getItem('token');
    if (token) {
      try {
        const res = await api.get('/auth/me');
        setUser(res.data.user);
      } catch {
        localStorage.removeItem('token');
        setUser(null);
      }
    } else {
      setUser(null);
    }
    setLoading(false);
  }, []);

  useEffect(() => {
    loadUser();

    // Listen for storage changes from OTHER tabs
    const handleStorageChange = (e) => {
      if (e.key === 'token') {
        if (!e.newValue) {
          // Token was removed in another tab — log out this tab too
          setUser(null);
          window.location.href = '/';
        } else if (e.newValue !== e.oldValue) {
          // Token changed in another tab — reload user for this tab
          loadUser();
        }
      }
    };

    window.addEventListener('storage', handleStorageChange);
    return () => window.removeEventListener('storage', handleStorageChange);
  }, [loadUser]);

  const login = async (token, userData) => {
    // If already logged in, block login from another tab
    const existingToken = localStorage.getItem('token');
    if (existingToken && user) {
      return { error: 'Already logged in. Please logout first.' };
    }

    localStorage.setItem('token', token);
    setUser(userData);
    return { success: true };
  };

  const logout = () => {
    localStorage.removeItem('token');
    setUser(null);
    // Broadcast logout to all other tabs
    window.dispatchEvent(new StorageEvent('storage', {
      key: 'token',
      oldValue: localStorage.getItem('token'),
      newValue: null,
    }));
  };

  const refreshUser = async () => {
    try {
      const res = await api.get('/auth/me');
      setUser(res.data.user);
    } catch {}
  };

  return (
    <AuthContext.Provider value={{ user, loading, login, logout, refreshUser }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => useContext(AuthContext);
